import React from 'react';
// This is the corrected import for the modern 'uuid' library.
// Even if it's not used directly for a key, having the correct import
// in all components prevents these cascading render errors.
import { v4 as uuidv4 } from 'uuid';

const Icons = ({ setContent, content, theme }) => {
    const reactions = [
        '❤️', '😆', '😯', '😢', '😡', '👍', '👎', '😄',
        '😂', '😍', '😘', '😥', '🤔', '😏', '😬', '🙏'
    ];

    return (
        <div className="nav-item dropdown" style={{ opacity: 1 }}>
            <span className="nav-link position-relative px-1" id="navbarDropdown"
                role="button" data-bs-toggle="dropdown" aria-expanded="false">
                <span style={{ opacity: 0.4 }}>😄</span>
            </span>

            <div className="dropdown-menu" aria-labelledby="navbarDropdown">
                <div className="reactions">
                    {
                        reactions.map(icon => (
                            // Using a stable key since the list is static
                            <span key={icon} onClick={() => setContent(content + icon)}>
                                {icon}
                            </span>
                        ))
                    }
                </div>
            </div>
        </div>
    );
};

export default Icons;
